def edit_distance(source, target):
    m = len(source)
    n = len(target)
    table = []
    for i in range(m + 1):
        row = [0] * (n + 1)
        table.append(row)
    for i in range(m + 1):
        table[i][0] = i
    for j in range(n + 1):
        table[0][j] = j
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if source[i-1] == target[j-1]:
                cost = 0
            else:
                cost = 2
            sub = table[i-1][j-1] + cost
            ins = table[i][j-1] + 1
            dele = table[i-1][j] + 1
            table[i][j] = min(sub, ins, dele)
    return table[m][n]
def closest(word, dictionary):
    best_word = dictionary[0]
    min_dist = edit_distance(word, dictionary[0])
    for i in range(1, len(dictionary)):
        d = edit_distance(word, dictionary[i])
        if d < min_dist:
            min_dist = d
            best_word = dictionary[i]
    return best_word
print(edit_distance("intention", "execution"))

